// Compares two semantic version strings ("1.4.2", "2.0.0-rc.1", "1.0.0+build.5").
// Returns a negative number if a < b, 0 if they have equal precedence, positive if a > b.
// Precedence follows semver.org section 11.

export function parse(version: string): { core: string[]; pre: string[] } {
  const [withoutBuild] = version.split('+');
  const [core, pre] = withoutBuild.split('-');
  return { core: core.split('.'), pre: pre ? pre.split('.') : [] };
}

export function compareVersions(a: string, b: string): number {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    if (pa.core[i] !== pb.core[i]) return pa.core[i] < pb.core[i] ? -1 : 1;
  }
  if (pa.pre.length === 0 && pb.pre.length === 0) return 0;
  return pa.pre.join('.') < pb.pre.join('.') ? -1 : 1;
}

export function sortVersions(versions: string[]): string[] {
  return [...versions].sort(compareVersions);
}

input.command:
python3 - <<'E'
p='src/compare.ts'
s=open(p).read()
a=s.index('  const [core, pre]')
b=s.index('export function sortVersions')
new='''  const i = withoutBuild.indexOf('-');
  const core = i < 0 ? withoutBuild : withoutBuild.slice(0, i);
  const pre = i < 0 ? '' : withoutBuild.slice(i + 1);
  return { core: core.split('.'), pre: pre ? pre.split('.') : [] };
}

const isNum = (s: string) => /^\\d+$/.test(s);

export function compareVersions(a: string, b: string): number {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const x = Number(pa.core[i] ?? 0);
    const y = Number(pb.core[i] ?? 0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (pa.pre.length === 0 && pb.pre.length === 0) return 0;
  if (pa.pre.length === 0) return 1;
  if (pb.pre.length === 0) return -1;
  const n = Math.min(pa.pre.length, pb.pre.length);
  for (let i = 0; i < n; i++) {
    const x = pa.pre[i];
    const y = pb.pre[i];
    if (x === y) continue;
    const nx = isNum(x);
    const ny = isNum(y);
    if (nx && ny) return Number(x) < Number(y) ? -1 : 1;
    if (nx) return -1;
    if (ny) return 1;
    return x < y ? -1 : 1;
  }
  return Math.sign(pa.pre.length - pb.pre.length);
}

'''
open(p,'w').write(s[:a]+new+s[b:])
E
npm test 2>&1 | tail -20

